def vincular_tarefas(apps, schema_editor):
    Objetivo = apps.get_model('iativa_agent', 'Objetivo')
    Mensagem = apps.get_model('iativa_chat', 'Mensagem')
    Tarefa = apps.get_model('iativa_agent', 'Tarefa')
    for o in Objetivo.objects.filter(tarefa__isnull=True, exigencia='verificacao', situacao='cumprido').iterator():
        m = Mensagem.objects.filter(conversa_id=o.conversa_id, ficha__objetivo=o.pk,
                                    ficha__tipo='tarefa').order_by('-id').first()
        if m is None:
            continue
        t = Tarefa.objects.filter(pk=m.ficha.get('tarefa'), usuario_id=o.usuario_id,
                                   conversa_id=o.conversa_id).first()
        if t is None:
            continue
        cob = t.cobertura or {}
        completo = t.situacao == 'concluida' and cob.get('lista_completa') and not cob.get('sem_classificacao', 0)
        Objetivo.objects.filter(pk=o.pk).update(tarefa_id=t.pk,
            situacao='cumprido' if completo else 'aguardando_tarefa',
            melhor_evidencia='verificacao' if completo else '')


